const int16_t* fallback_pcm(Clip c, size_t& n) {
    switch (c) {
        case Clip::ToneWarn: n = sizeof(kTone_warn) / 2; return kTone_warn;
        case Clip::ToneInfo: n = sizeof(kTone_info) / 2; return kTone_info;
        default: n = 0; return nullptr;
    }
}

